  fd_review: { en: "Check the record on screen while it is read aloud.", hi: "रिकॉर्ड सुनते हुए स्क्रीन पर देखिए।", kn: "ಓದಿ ಹೇಳುವಾಗ ಪರದೆಯಲ್ಲಿ ದಾಖಲೆ ನೋಡಿ." },
  fd_correct: { en: "Say what to change, for example “No, weight is 54 kilo”.", hi: "जो बदलना है बोलिए, जैसे “नहीं, वज़न 54 किलो है”।", kn: "ಬದಲಿಸಬೇಕಾದ್ದನ್ನು ಹೇಳಿ, ಉದಾ: “ಇಲ್ಲ, ತೂಕ 54 ಕಿಲೋ”." },
  fd_confirm: { en: "Say “yes” or tap Confirm.", hi: "“हाँ” बोलिए या पक्का करें दबाइए।", kn: "“ಹೌದು” ಎನ್ನಿ ಅಥವಾ ಖಚಿತಪಡಿಸಿ ಒತ್ತಿ." },
  fd_save: { en: "The record is saved only after the server confirms it.", hi: "सर्वर की पुष्टि के बाद ही रिकॉर्ड सेव होता है।", kn: "ಸರ್ವರ್ ಖಚಿತಪಡಿಸಿದ ನಂತರವೇ ದಾಖಲೆ ಸೇವ್ ಆಗುತ್ತದೆ." },
