  ws_start_title: { en: "Start a visit", hi: "विज़िट शुरू करें", kn: "ಭೇಟಿ ಪ್ರಾರಂಭಿಸಿ" },
  ws_start_body: { en: "Choose the language you will speak in, confirm consent and start. Nothing is saved until you confirm the record.", hi: "बोलने की भाषा चुनें, सहमति दें और शुरू करें। रिकॉर्ड पक्का करने तक कुछ सेव नहीं होगा।", kn: "ಮಾತನಾಡುವ ಭಾಷೆ ಆಯ್ಕೆಮಾಡಿ, ಒಪ್ಪಿಗೆ ನೀಡಿ ಪ್ರಾರಂಭಿಸಿ. ದಾಖಲೆ ಖಚಿತಪಡಿಸುವವರೆಗೆ ಏನೂ ಸೇವ್ ಆಗುವುದಿಲ್ಲ." },
