  start_live: { en: "Start live visit", hi: "लाइव विज़िट शुरू करें", kn: "ಲೈವ್ ಭೇಟಿ ಪ್ರಾರಂಭಿಸಿ" },
  start_demo: { en: "Run demo without microphone", hi: "बिना माइक डेमो चलाएँ", kn: "ಮೈಕ್ ಇಲ್ಲದೆ ಡೆಮೊ ನಡೆಸಿ" },
  demo_explain: { en: "Demo mode plays sample notes, never calls Gnani and is labelled on every screen. Demo visits are saved with source “demo”.", hi: "डेमो मोड नमूना नोट्स चलाता है, Gnani को कॉल नहीं करता और हर स्क्रीन पर चिह्नित रहता है। डेमो विज़िट “demo” स्रोत से सेव होती हैं।", kn: "ಡೆಮೊ ಮೋಡ್ ಮಾದರಿ ನೋಟ್ ಬಳಸುತ್ತದೆ, Gnani ಕರೆಯುವುದಿಲ್ಲ, ಪ್ರತಿ ಪರದೆಯಲ್ಲಿ ಗುರುತಿಸಲಾಗಿದೆ. ಡೆಮೊ ಭೇಟಿಗಳು “demo” ಮೂಲದೊಂದಿಗೆ ಸೇವ್ ಆಗುತ್ತವೆ." },
  live_unavailable: { en: "Live speech is not configured on the server (Gnani key missing). Demo mode still works.", hi: "सर्वर पर लाइव स्पीच सेट नहीं है (Gnani की नहीं है)। डेमो मोड चलता है।", kn: "ಸರ್ವರ್‌ನಲ್ಲಿ ಲೈವ್ ಸ್ಪೀಚ್ ಸಿದ್ಧವಿಲ್ಲ (Gnani ಕೀ ಇಲ್ಲ). ಡೆಮೊ ಮೋಡ್ ಕೆಲಸ ಮಾಡುತ್ತದೆ." },
  server_unreachable: { en: "The server is not reachable, so a visit cannot start. Check that the backend is running.", hi: "सर्वर से संपर्क नहीं हो रहा, इसलिए विज़िट शुरू नहीं हो सकती। बैकएंड चल रहा है या नहीं जाँचें।", kn: "ಸರ್ವರ್ ತಲುಪಲಾಗುತ್ತಿಲ್ಲ, ಭೇಟಿ ಪ್ರಾರಂಭವಾಗದು. ಬ್ಯಾಕೆಂಡ್ ಚಾಲನೆಯಲ್ಲಿದೆಯೇ ಪರಿಶೀಲಿಸಿ." },
