  hint_offline: { en: "Live speech unavailable. The draft is kept on this device and is not saved.", hi: "लाइव स्पीच उपलब्ध नहीं। ड्राफ़्ट इस डिवाइस पर रखा है, सेव नहीं हुआ।", kn: "ಲೈವ್ ಸ್ಪೀಚ್ ಲಭ್ಯವಿಲ್ಲ. ಡ್ರಾಫ್ಟ್ ಈ ಸಾಧನದಲ್ಲಿದೆ, ಸೇವ್ ಆಗಿಲ್ಲ." },
  hint_reconnecting: { en: "Connection dropped. Reconnecting; your draft is safe.", hi: "कनेक्शन टूटा। फिर से जुड़ रहा है; ड्राफ़्ट सुरक्षित है।", kn: "ಸಂಪರ್ಕ ತಪ್ಪಿದೆ. ಮರುಸಂಪರ್ಕಿಸುತ್ತಿದೆ; ಡ್ರಾಫ್ಟ್ ಸುರಕ್ಷಿತ." },
  hint_saving: { en: "Saving to the register.", hi: "रजिस्टर में सेव हो रहा है।", kn: "ರಿಜಿಸ್ಟರ್‌ಗೆ ಸೇವ್ ಆಗುತ್ತಿದೆ." },
  hint_demo: { en: "Demo mode: tap a sample note below. No microphone is used.", hi: "डेमो मोड: नीचे नमूना नोट चुनें। माइक इस्तेमाल नहीं होता।", kn: "ಡೆಮೊ ಮೋಡ್: ಕೆಳಗೆ ಮಾದರಿ ನೋಟ್ ಆಯ್ಕೆಮಾಡಿ. ಮೈಕ್ ಬಳಸುವುದಿಲ್ಲ." },
