export type Key = keyof typeof S;

const STORED = "asha.lang";

function initial(): Lang {
  try {
    const v = localStorage.getItem(STORED);
    if (v === "en" || v === "hi" || v === "kn") return v;
  } catch { /* storage unavailable */ }
  return "en";
}

let current: Lang = initial();

export function lang(): Lang {
  return current;
}

export function setLang(l: Lang): void {
  current = l;
  try { localStorage.setItem(STORED, l); } catch { /* storage may be unavailable */ }
  if (typeof document !== "undefined" && document.documentElement) document.documentElement.lang = l;
}

export function tr(key: Key, l: Lang = current): string {
  const entry = S[key] as Record<Lang, string>;
  return entry[l] || entry.en;
}

/** tr() with {placeholder} substitution. Values are plain text (callers still escape on render). */
export function trf(key: Key, vars: Record<string, string | number>, l: Lang = current): string {
  return tr(key, l).replace(/\{(\w+)\}/g, (_m, k: string) => (k in vars ? String(vars[k]) : `{${k}}`));
}

export const LANGUAGES: { code: Lang; label: string; sub: Key }[] = [
  { code: "en", label: "English", sub: "lang_en_sub" },
  { code: "hi", label: "हिन्दी", sub: "lang_hi_sub" },
  { code: "kn", label: "ಕನ್ನಡ", sub: "lang_kn_sub" },
];

export function allKeys(): Key[] {
  return Object.keys(S) as Key[];
}
